{"code": "from collections import defaultdict
import numpy as np
lab=load_lab(); gs=defaultdict(list)
for r in lab:
 if r['family']=='univariate_regression' and r['optimizer']['type']=='SGD' and r['activation'] in ['silu','gelu'] and not r.get('excluded') and not r.get('failed_seeds'): gs[r['set_id']].append(r)
for regime in ['all','plain','residual']:
 pairs=[]
 for rs in gs.values():
  for a in rs:
   for b in rs:
    if (regime=='plain' and a['residual']) or (regime=='residual' and not a['residual']):continue
    if a['optimizer']==b['optimizer'] and a['depth']==b['depth'] and a['n_ln']==b['n_ln'] and a['n_ln']>0 and a['residual']==b['residual'] and a['activation']==b['activation']:
     ia=[i for i,x in enumerate(a['layer_norm']) if x]; ib=[i for i,x in enumerate(b['layer_norm']) if x]
     if sum(ia)>sum(ib):pairs.append((a,b))
 print(regime,'later LN',len(pairs),'wins',sum(a['mean']<b['mean'] for a,b in pairs),'sets',len(set(a['set_id'] for a,b in pairs)))
 for a,b in pairs:print(a['dataset_id'],a['depth'],a['width'],b['width'],a['layer_norm'],b['layer_norm'],a['mean']/b['mean'])
